/// <summary>
/// Base class for PricingAttribute table <c>MCRCustCategory</c>.
/// </summary>
internal abstract class GUPPricingAttributeMCRCustCategory extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{

}

Method.Source:
    protected MCRCustCategory getTableRecord(Common _pricingObject)
    {
        SalesTable      salesTable = _pricingObject as SalesTable;
        MCRCustCategory mCRCustCategory;

        if (salesTable)
        {
            mCRCustCategory = GUPPricingAttributeMCRCustCategory::findByCustomer(salesTable.custTable_CustAccount().RecId);
        }

        return mCRCustCategory;
    }

    static MCRCustCategory findByCustomer(RefRecId _custTableRecId)
    {
        MCRCustCategory mCRCustCategory;

        if (_custTableRecId)
        {
            select firstonly mCRCustCategory
                where mCRCustCategory.Customer == _custTableRecId;
        }

        return mCRCustCategory;
    }

    protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
    {
        QueryBuildDataSource qbds, qbdsRoot;

        if (_qbdsMap && _qbdsMap.exists(tableStr(CustTable)))
        {
            qbdsRoot = _qbdsMap.lookup(tableStr(CustTable));
        }
        else
        {
            qbdsRoot = _query.addDataSource(tableNum(CustTable));

            if (_qbdsMap)
            {
                _qbdsMap.insert(tableStr(CustTable), qbdsRoot);
            }
        }

        if (_qbdsMap && _qbdsMap.exists(this.getQueryBuilderDatasourceIdentifier()))
        {
            qbds = _qbdsMap.lookup(this.getQueryBuilderDatasourceIdentifier());
        }
        else
        {
            qbds = qbdsRoot.addDataSource(tableNum(MCRCustCategory));
            qbds.addLink(fieldNum(CustTable, RecId), fieldNum(MCRCustCategory, Customer));
            qbds.joinMode(JoinMode::ExistsJoin);
            
            if (_qbdsMap)
            {
                _qbdsMap.insert(this.getQueryBuilderDatasourceIdentifier(), qbds);
            }
        }

        return qbds;
    }

    public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
    {
        QueryBuildDataSource qbds;

        qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
        this.setQueryBuildDatasourceRange(qbds, _value);

        return _query;
    }
